cat > /workspace/tmp/t3.py <<'EOF'
import json, subprocess, sys
def run(scn):
    p = subprocess.run([sys.executable,'/workspace/submission/bridge.py'], input=json.dumps(scn).encode(),
                       stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if p.returncode: raise SystemExit(p.stderr.decode())
    return json.loads(p.stdout)
R = {"https://demo.test":"a","https://other.test":"b"}
def ev(sid,t,**kw):
    d={'sid':sid,'type':t}; d.update(kw); return d
def hdr(path, method='GET', auth='demo.test', extra=()):
    return [list(p) for p in [(':method',method),(':scheme','https'),(':authority',auth),(':path',path)]+list(extra)]

# FIN order differs from sid order
scn = {'routes':R,'events':[
  ev(8,'headers',fields=hdr('/eight')),
  ev(0,'headers',fields=hdr('/zero')),
  ev(4,'headers',fields=hdr('/four')),
  ev(4,'fin'),          # index 3 -> first in pipeline
  ev(8,'fin'),          # index 4
  ev(0,'fin'),          # index 5
]}
r = run(scn)
print(json.dumps(r['streams'], indent=None))
print(repr(bytes.fromhex(r['origins']['a']).decode()))
EOF
cd /workspace && python3 tmp/t3.py && python3 submission/bridge.py < examples/scenario.json > tmp/out.json && python3 inspect_pipeline.py tmp/out.json
